const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const la_geom = ee.Geometry.Rectangle([-118.8, 33.7, -117.8, 34.3]); // Bounding box for Los Angeles area
  const band = 'tropospheric_NO2_column_number_density';
  const collection_name = 'COPERNICUS/S5P/OFFL/L3_NO2';

  // 2. Data Acquisition and Processing Function
  const get_mean_no2 = (year) => {
    const start_date = ee.Date.fromYMD(year, 10, 1);
    const end_date = ee.Date.fromYMD(year, 10, 23).advance(1, 'day');

    const collection = ee.ImageCollection(collection_name)
      .filterBounds(la_geom)
      .filterDate(start_date, end_date)
      .select([band, 'cloud_fraction']);

    // Check for empty collection
    const size = collection.size().getInfo();
    if (size === 0) {
      return { 'mean': null, 'count': null, 'size': 0 };
    }

    // Mask pixels with cloud fraction > 20%
    const cloud_masked = collection.map(function(image) {
      const cloud_mask = image.select('cloud_fraction').lte(0.2);
      return image.updateMask(cloud_mask);
    });

    const mean_image = cloud_masked.select(band).mean();

    const stats = mean_image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: la_geom,
      scale: 3000,
      maxPixels: 1e9
    });

    // Use .get() to retrieve server-side objects, then getInfo() once
    return {
        'mean': stats.get(band + '_mean'),
        'count': stats.get(band + '_count'),
        'size': size
    };
  };

  // 3. Calculation
  const result_2021 = get_mean_no2(2021);
  const result_2019 = get_mean_no2(2019);
  const result_2018 = get_mean_no2(2018);

  // Perform server-side computations before calling getInfo()
  const all_stats = ee.Dictionary({
      '2021': result_2021,
      '2019': result_2019,
      '2018': result_2018
  }).getInfo();

  const val_2021 = all_stats['2021'];
  const val_2019 = all_stats['2019'];
  const val_2018 = all_stats['2018'];

  // 4. Validation & Final Answer
  if (val_2021.size === 0 || val_2019.size === 0 || val_2018.size === 0) {
    console.log(`Image counts - 2021: ${val_2021.size}, 2019: ${val_2019.size}, 2018: ${val_2018.size}`);
    console.log('Evidence: No images found for at least one period.');
    console.log('C1');
    return;
  }

  if (val_2021.count === 0 || val_2019.count === 0 || val_2018.count === 0) {
    console.log(`Valid pixel counts - 2021: ${val_2021.count}, 2019: ${val_2019.count}, 2018: ${val_2018.count}`);
    console.log('Evidence: Zero valid pixels after cloud masking for at least one period.');
    console.log('C2');
    return;
  }

  if (val_2021.mean === null || val_2019.mean === null || val_2018.mean === null) {
    console.log(`Mean values - 2021: ${val_2021.mean}, 2019: ${val_2019.mean}, 2018: ${val_2018.mean}`);
    console.log('Evidence: Calculation failed, resulting in a null value.');
    console.log('C3');
    return;
  }

  const mean_ref = (val_2019.mean + val_2018.mean) / 2;

  console.log(`Period: Oct 1-23`);
  console.log(`Los Angeles Tropospheric NO2 (mol/m^2)`);
  console.log(`2021 Mean: ${val_2021.mean.toExponential(3)}, Pixels: ${val_2021.count}`);
  console.log(`2019 Mean: ${val_2019.mean.toExponential(3)}, Pixels: ${val_2019.count}`);
  console.log(`2018 Mean: ${val_2018.mean.toExponential(3)}, Pixels: ${val_2018.count}`);
  console.log(`2018-2019 Average: ${mean_ref.toExponential(3)}`);

  if (val_2021.mean < mean_ref) {
    console.log('Evidence: 2021 NO2 concentration is lower than the 2018-2019 average.');
    console.log('A');
  } else {
    console.log('Evidence: 2021 NO2 concentration is not lower than the 2018-2019 average.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log('D');
});
